create table xxcus.xxcmp_requests (
    request_id            number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    request_number        varchar2(30 byte) not null enable,
    request_type          varchar2(30 byte) default 'NEW_ONBOARDING' not null enable,
    trigger_source        varchar2(30 byte) default 'MANUAL' not null enable,
    parent_request_id     number,
    parent_case_id        number,
    party_id              number,
    party_type            varchar2(30 byte) not null enable,
    party_name            varchar2(360 byte) not null enable,
    registration_number   varchar2(100 byte),
    jurisdiction          varchar2(30 byte),
    entity_type           varchar2(30 byte),
    date_of_birth         date,
    nationality           varchar2(30 byte),
    requesting_department varchar2(240 byte),
    requester_user_name   varchar2(255 byte) not null enable,
    questionnaire_code    varchar2(30 byte),
    intake_score          number,
    intake_critical_flag  varchar2(1 byte),
    intake_outcome        varchar2(30 byte),
    request_status        varchar2(30 byte) default 'DRAFT' not null enable,
    justification         varchar2(4000 byte),
    submitted_date        timestamp(6),
    completed_date        timestamp(6),
    workflow_id           number,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable,
    party_selection       varchar2(10 byte) default 'NEW',
    incorporation_date    date,
    id_type               varchar2(30 byte),
    id_number             varchar2(100 byte),
    match_ack_flag        varchar2(1 byte) default 'N',
    match_status          varchar2(20 byte),
    match_resolved_by     varchar2(255 byte),
    match_resolved_date   timestamp(6),
    match_note            varchar2(1000 byte)
);

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_ck1
        check ( request_type in ( 'NEW_ONBOARDING', 'PERIODIC_REVIEW', 'EVENT_TRIGGERED_REVIEW' ) ) enable;

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_ck2
        check ( trigger_source in ( 'MANUAL', 'SCHEDULED', 'EVENT_DRIVEN' ) ) enable;

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_ck3
        check ( request_status in ( 'DRAFT', 'SUBMITTED', 'IN_PROGRESS', 'COMPLETED', 'REJECTED',
                                    'CANCELLED' ) ) enable;

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_ck4
        check ( intake_outcome in ( 'NOT_REQUIRED', 'AUTO_APPROVED', 'ASSIGNED' ) ) enable;

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_ck5
        check ( party_type in ( 'ORGANIZATION', 'PERSON' ) ) enable;

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_ck6
        check ( intake_critical_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_requests
    add constraint xxcmp_requests_pk primary key ( request_id )
        using index enable;

alter table xxcus.xxcmp_requests add constraint xxcmp_requests_uk1 unique ( request_number )
    using index enable;


